int vhost_get_vring_buf(struct vhost_dev *dev, u64 addr, u32 len,
                        struct iovec iov[], int iov_size)
{
    struct vhost_memory *mem = dev->mem;
    struct vhost_memory_region *reg;
    int niov = 0;
    int i;

    mutex_lock(&dev->mem_mutex);

    for (i = 0; i < mem->nregions; ++i) {
        reg = &mem->regions[i];
        u64 start = reg->guest_phys_addr;
        u64 end = start + reg->memory_size - 1;
        u64 intersection_start = max(addr, start);
        u64 intersection_end = min(addr + len - 1, end);
        u64 page_start, page_end;
        u64 page_offset;

        if (intersection_start > intersection_end)
            continue;

        page_offset = intersection_start % VHOST_PAGE_SIZE;
        page_start = intersection_start - page_offset;
        page_end = (intersection_end + VHOST_PAGE_SIZE - 1)
                   & ~(VHOST_PAGE_SIZE - 1);

        while (page_start < page_end) {
            u64 page_guest_phys = page_start;
            u64 page_len = min(page_start + VHOST_PAGE_SIZE, page_end) - page_start;
            u64 offset = max(page_guest_phys, addr) - addr;
            u64 guest_len = min(len - offset, page_len);
            u64 host_phys = reg->userspace_addr +
                            (page_guest_phys - reg->guest_phys_addr) +
                            (offset % VHOST_PAGE_SIZE);

            if (niov >= iov_size) {
                mutex_unlock(&dev->mem_mutex);
                return -EFAULT;
            }

            iov[niov].iov_base = (void *)((uintptr_t)host_phys);
            iov[niov].iov_len = guest_len;
            niov++;

            page_start += VHOST_PAGE_SIZE;
        }
    }

    mutex_unlock(&dev->mem_mutex);

    if (niov == 0)
        return -EFAULT;

    return niov;
}

int vhost_get_vhost_memory(struct vhost_dev *dev, u64 addr, u32 len,
                           struct iovec iov[], int iov_size)
{
    int n = 0;
    int ret = 0;
    struct vhost_memory *mem = dev->memory;
    struct vhost_memory_region *reg;
    size_t i;

    if (!mem || !mem->regions || mem->nregions <= 0)
        return -EFAULT;

    mutex_lock(&dev->mem_lock);

    for (i = 0; i < mem->nregions && len > 0; i++) {
        reg = &mem->regions[i];
        u64 reg_start = reg->guest_phys_addr;
        u64 reg_end = reg->guest_phys_addr + reg->size;
        u64 start = max(addr, reg_start);
        u64 end = min(addr + len, reg_end);
        size_t offset = start - reg->guest_phys_addr;

        if (start >= end)
            continue;

        iov[n].iov_base = reg->userspace_addr + offset;
        iov[n].iov_len = end - start;
        n++;

        if (n >= iov_size) {
            ret = -EFAULT;
            break;
        }

        addr = end;
    }

    mutex_unlock(&dev->mem_lock);

    if (n == 0)
        ret = -EFAULT;

    return ret ?: n;
}

int vhost_get_vhost_dev_iov(struct vhost_dev *dev, u64 addr, u32 len,
                            struct iovec iov[], int iov_size)
{
    int i = 0;
    unsigned int n;
    struct vhost_memory *mem;
    struct vhost_memory_region *reg;
    unsigned long offset;

    if (iov_size <= 0)
        return -EINVAL;

    mem = dev->memory;
    if (!mem)
        return -EFAULT;

    vhost_dev_lock(dev);

    for (n = 0; n < len; n++) {
        if (!dev->memory->regions || i >= iov_size)
            break;

        reg = &dev->memory->regions[i];
        if (!reg || !reg->userspace_addr)
            break;

        offset = addr - reg->guest_phys_addr;
        if (offset >= reg->size)
            break;

        iov[i].iov_base = (void __user *)((unsigned long)reg->userspace_addr + offset);
        iov[i].iov_len = min(len, (size_t)(reg->size - offset));
        i++;

        addr += iov[i - 1].iov_len;
        len -= iov[i - 1].iov_len;
    }

    vhost_dev_unlock(dev);

    if (i == 0 && n < len)
        return -EFAULT;

    return i;
}

int vhost_dev_translate(struct vhost_dev *dev, u64 addr, u32 len,
                        struct iovec iov[], int iov_size)
{
    int i = 0;
    int ret = 0;
    u64 start = addr;
    u64 end = addr + len;

    if (!dev || !iov || iov_size <= 0) {
        return -EINVAL;
    }

    mutex_lock(&dev->mem->mutex);

    while (start < end && i < iov_size) {
        struct vhost_vring_memory *mem = dev->mem;
        struct vhost_memory_region *region;
        int j;

        for (j = 0; j < mem->nregions; j++) {
            region = &mem->regions[j];
            if (start >= region->guest_phys_addr &&
                start < region->guest_phys_addr + region->memory_size) {
                u64 region_start = region->guest_phys_addr;
                u64 region_end = region->guest_phys_addr + region->memory_size;
                u64 overlap_start = max(start, region_start);
                u64 overlap_end = min(end, region_end);
                u64 offset = overlap_start - start;

                iov[i].iov_base = region->userspace_addr + offset;
                iov[i].iov_len = overlap_end - overlap_start;
                i++;
                start = overlap_end;
                break;
            }
        }

        if (j == mem->nregions) {
            ret = -EFAULT;
            break;
        }
    }

    if (start < end) {
        ret = -ENOBUFS;
    }

    mutex_unlock(&dev->mem->mutex);
    return ret ? ret : i;
}

int vhost_get_readonly_iov(struct vhost_dev *dev, u64 addr, u32 len,
                          struct iovec iov[], int iov_size)
{
    struct vhost_memory *mem = dev->memory;
    struct vhost_memory_region *reg;
    int i;
    int niov = 0;
    int ret = 0;

    vhost_dev_lock_read(dev);

    for (i = 0; i < mem->nregions; ++i) {
        reg = &mem->regions[i];
        u64 offset = addr - reg->guest_phys_addr;

        if (offset > reg->size)
            continue;

        if (offset + len > reg->size) {
            ret = -EFAULT;
            goto error;
        }

        iov[niov].iov_base = reg->userspace_addr + offset;
        iov[niov].iov_len = len;
        ++niov;

        if (niov >= iov_size) {
            ret = -ENOBUFS;
            goto error;
        }

        break;
    }

    if (i == mem->nregions) {
        ret = -EFAULT;
        goto error;
    }

    vhost_dev_unlock_read(dev);
    return niov;

error:
    vhost_dev_unlock_read(dev);
    return ret;
}
